        rsx! {
            elements::TyDataTable {
                caption: "Customers",
                caption_visible: true,
                columns: COLUMNS,
                rows: ROWS,
                sort_column: "name",
                sort_direction: elements::DataTableSortDirection::Ascending,
                max_block_size: "20rem",
                instance: "i",
            }
        }
